/*
 * onnx2c_memmap.h  (PPU / ARC EV export)
 * --------------------------------------
 * User-editable memory placement for this folder's onnx2c (DEEPCRAFT /
 * Viper Studio) ARC-vector export.
 *
 * model_onnx2c.c includes this file automatically when the PPU build defines
 * ONNX2C_MEMMAP (see ".cproject" -> "PPU Debug (Ext. MetaWare)" -> MetaWare C
 * Compiler -> "Preprocessor Defines"). Because this file is hand-maintained
 * (not generated by onnx2c), it survives regenerating model.c / model_onnx2c.c
 * from a new model export.
 *
 * WHY THIS FILE EXISTS
 * --------------------
 * The generated model declares every tensor with an ATTR_<RO|RW>_<region>
 * macro, where <region> comes from the memory configuration used at export
 * time. Depending on the exporter version some of those are hard-coded to a
 * real section and the rest chain to ATTR_RO_DEFAULT / ATTR_RW_DEFAULT, which
 * the generated file leaves EMPTY.
 *
 * For a NON-__vccm tensor an empty attribute is not "put it in the region
 * onnx2c intended" - it means plain C linkage, so `const` tensors end up in
 * LIT/.rodata, which PPU/Lcf_Metaware_ArcEV_Ppu.lsl maps straight into
 * PFLASH5.PPU. The kernels then read every weight from program flash over the
 * SRI bus instead of from local RAM, which is orders of magnitude slower and
 * shows up as multi-hundred-millisecond inferences and CPU0 dispatch timeouts.
 *
 * For a __vccm tensor an empty attribute is exactly right, and a section
 * attribute is actively harmful - see the CRITICAL note on ATTR_RO_VCCM below.
 *
 * This header maps each onnx2c region onto the matching section that the PPU
 * linker script actually defines, so tensors land where the export intended.
 *
 * REGION -> SECTION -> MEMORY (see PPU/Lcf_Metaware_ArcEV_Ppu.lsl)
 *   VCCM    .vdata / .vbss       VCCM       128K  vector RAM, fastest, shared
 *                                                 with the vector stack;
 *                                                 tensors here are __vccm
 *   CSM_RW  .csm.data/.csm.bss   CSM        512K  PPU-local RAM, fast
 *   LMU     .data / .bss         LMU9.CACHED 256K on-chip LMU, slower
 *   Flash   (see note below)     PFLASH5.PPU 1M   read in place, slowest
 *
 * ".vdata", ".csm.data" and ".data" are initialised sections: they are listed
 * in the linker script's INITDATA line, so the ARC startup code copies them
 * from flash into RAM before main(). The ".*bss" variants are NOLOAD.
 *
 * VERIFY PLACEMENT IN THE .map AFTER EVERY CHANGE HERE. VCCM symbols are at
 * 0xC000xxxx, CSM at 0x9208xxxx, LMU at 0x9088xxxx, flash at 0x813xxxxx. If a
 * tensor declared __vccm is not at 0xC000xxxx, the model will produce
 * plausible-looking but meaningless output.
 */
#ifndef ONNX2C_MEMMAP_H
#define ONNX2C_MEMMAP_H

/* --- VCCM: vector RAM. Fastest, but only 128K and it also has to hold the
 * vector stack (see LCF_VEC_STACKSIZE in PPU/Lcf_Metaware_ArcEV_Ppu.lsl).
 * onnx2c puts the read/write scratch tensors (tu0/tu1) here, plus the smaller
 * weight tensors.
 *
 * CRITICAL: these tensors are declared `const float __vccm ...`. The __vccm
 * qualifier is address_space(4), which makes the compiler emit VCCM-aperture
 * accesses for them. A section attribute moves the BYTES but not the ACCESS
 * PATH, so these may only ever be mapped onto a VCCM-backed section
 * (.vdata / .vbss). Point them at .csm.data or .data and every read silently
 * fetches unrelated VCCM contents instead - the model still runs and still
 * varies with its input, it just returns nonsense. */
#ifndef ATTR_RO_VCCM
#define ATTR_RO_VCCM __attribute__((section(".vdata")))
#endif
#ifndef ATTR_RW_VCCM
#define ATTR_RW_VCCM __attribute__((section(".vbss")))
#endif

/* --- CSM: PPU-local RAM, 512K. Where onnx2c puts the larger weight tensors.
 * These are declared WITHOUT __vccm and are read with ordinary scalar loads,
 * so they can live anywhere. Keeping them out of flash is what makes
 * inference fast. */
#ifndef ATTR_RO_CSM_RW
#define ATTR_RO_CSM_RW __attribute__((section(".csm.data")))
#endif
#ifndef ATTR_RW_CSM_RW
#define ATTR_RW_CSM_RW __attribute__((section(".csm.bss")))
#endif

/* --- LMU9 cached, 256K. Slower than VCCM/CSM but useful overflow space.
 * Also non-__vccm. */
#ifndef ATTR_RO_LMU
#define ATTR_RO_LMU __attribute__((section(".data")))
#endif
#ifndef ATTR_RW_LMU
#define ATTR_RW_LMU __attribute__((section(".bss")))
#endif

/* --- ATTR_RO_DEFAULT / ATTR_RW_DEFAULT are deliberately NOT defined here.
 *
 * Every ATTR_<RO|RW>_<region> the generated file does not hard-code chains to
 * these, and that includes the __vccm-qualified VCCM tensors. Giving the
 * defaults a concrete section therefore silently drags __vccm objects out of
 * VCCM and breaks every vector load of them (see the CRITICAL note above -
 * this exact mistake produced a model that ran, consumed its input, and
 * returned a near-uniform softmax with ~13% argmax agreement).
 *
 * Leaving them to the generated file's empty fallback is what lets the
 * compiler place __vccm objects in VCCM by itself. If a future export leaves a
 * NON-__vccm region chaining to the default and its tensors end up in flash
 * (address 0x813xxxxx in the .map), add that specific region above rather than
 * giving the defaults a section. */

/* NOTE on the export's "Flash" region: the generated file defines
 * ATTR_RO_Flash as .rodata and ATTR_RW_Flash as .sdata. Neither is a good fit
 * for this linker script - it collects constants via `*(LIT)` rather than a
 * named .rodata output section, and its .sdata/.sbss groups are commented out
 * ("the current version of hal (speed) does not support sdata / sbss"). This
 * header therefore leaves them alone. If a future export actually places
 * tensors in the Flash region, add matching output sections to
 * PPU/Lcf_Metaware_ArcEV_Ppu.lsl first and verify placement in the .map file. */

#endif /* ONNX2C_MEMMAP_H */
